import ee, math
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
geom = ee.Geometry.Polygon([
    [-70.0, -14.5],
    [-70.0,  -7.0],
    [-58.0,  -7.0],
    [-58.0, -14.5],
    [-70.0, -14.5],
])

def get_august_aod(year):
    start = ee.Date.fromYMD(year, 8, 1)
    end = ee.Date.fromYMD(year, 9, 1)
    datasets = [
        ('MODIS/061/MOD08_M3', 'Terra'),
        ('MODIS/061/MYD08_M3', 'Aqua'),
    ]
    band_candidates = [
        'Aerosol_Optical_Depth_Land_Mean_Mean',
        'Aerosol_Optical_Depth_Land_Ocean_Mean_Mean'
    ]
    for ds, name in datasets:
        col = ee.ImageCollection(ds).filterDate(start, end)
        size = col.size().getInfo()
        if size == 0:
            continue
        img = ee.Image(col.first())
        # Pick an available band
        try:
            bands = img.bandNames().getInfo()
        except Exception as e:
            print(f"{year} {name}: failed to read bands: {e}")
            return {'tag': 'D'}
        band = None
        for cand in band_candidates:
            if cand in bands:
                band = cand
                break
        if band is None:
            print(f"{year} {name}: Expected AOD band not found.")
            return {'tag': 'D'}
        # Compute count and mean
        try:
            stats = img.select(band).reduceRegion(
                reducer=ee.Reducer.combine(
                    reducers=[ee.Reducer.count(), ee.Reducer.mean()],
                    sharedInputs=True
                ),
                geometry=geom,
                scale=50000,
                maxPixels=1e9,
                tileScale=2
            ).get(band).getInfo()
        except Exception as e:
            print(f"{year} {name}: reduceRegion error: {e}")
            return {'tag': 'D'}
        if stats is None:
            return {'tag': 'C3'}
        count = stats['count']
        mean = stats['mean']
        return {
            'dataset': name,
            'size': size,
            'band': band,
            'count': int(count) if count is not None else 0,
            'mean': float(mean) if mean is not None else None,
            'tag': None
        }
    return {'tag': 'C1'}  # No images in both Terra and Aqua

def validate_result(res, year):
    if res.get('tag'):
        return res['tag']
    if res['size'] == 0:
        print(f"{year}: 0 images.")
        return 'C1'
    if res['count'] == 0:
        print(f"{year}: No valid pixels after processing.")
        return 'C2'
    val = res['mean']
    if val is None or math.isnan(val) or val < 0 or val > 10:
        print(f"{year}: Invalid mean value: {val}")
        return 'C3'
    return None

try:
    r2002 = get_august_aod(2002)
    if r2002.get('tag'):
        print("2002: retrieval failed.")
        print(r2002['tag'])
        raise SystemExit
    r2018 = get_august_aod(2018)
    if r2018.get('tag'):
        print("2018: retrieval failed.")
        print(r2018['tag'])
        raise SystemExit

    # Validations
    v2002 = validate_result(r2002, 2002)
    if v2002:
        print(v2002)
        raise SystemExit
    v2018 = validate_result(r2018, 2018)
    if v2018:
        print(v2018)
        raise SystemExit

    # Print concise evidence
    print(f"Aug 2002 Images: {r2002['size']} ({r2002['dataset']}), Band: {r2002['band']}")
    print(f"Aug 2018 Images: {r2018['size']} ({r2018['dataset']}), Band: {r2018['band']}")
    print(f"Aug 2002 AOD mean: {r2002['mean']:.3f}, pixels: {r2002['count']}")
    print(f"Aug 2018 AOD mean: {r2018['mean']:.3f}, pixels: {r2018['count']}")
    diff = r2018['mean'] - r2002['mean']
    pct = (diff / r2002['mean']) * 100.0 if r2002['mean'] != 0 else float('nan')
    print(f"Change (2018-2002): {diff:.3f} ({pct:.1f}%)")

    # Final Answer
    if r2018['mean'] < r2002['mean']:
        print("A")
    else:
        print("B")

except SystemExit:
    pass
except Exception as e:
    print(f"Error: {e}")
    print("D")

